"""A coordinator that spawns managed Devins, seen through the job API.

The coordinator is the session this app creates; legs are discovered from its
`child_session_ids`. Leg artifacts land in per-leg directories and are merged
into the flat job layout the UI reads by bare filename.
"""

from __future__ import annotations

import json
import time
from pathlib import Path
from typing import Any

import pytest

from backend.app import executor, store as store_module
from backend.app.artifacts import job_dir, leg_ids, run_dir
from backend.app.models import JobStatus
from backend.app.settings import settings

COORDINATOR = "coordinator-session"
LEGS = ("leg-one-session", "leg-two-session")


class FanoutDevin:
    """A coordinator that reports two children, each with its own artifacts."""

    def __init__(self) -> None:
        self.children: list[str] = []
        self.per_session_files: dict[str, dict[str, bytes]] = {
            LEGS[0]: {
                "conservation.json": json.dumps({"columns": [{"target_position": 160}]}).encode(),
            },
            LEGS[1]: {
                # Same filename, different content: the collision case.
                "conservation.json": json.dumps({"columns": [{"target_position": 208}]}).encode(),
            },
            COORDINATOR: {
                "final_result.json": json.dumps({"limitations": ["All results are CALCULATED."]}).encode(),
            },
        }

    def create_session(self, prompt: str, title: str, playbook_id: str | None = None) -> dict[str, Any]:
        return {"session_id": COORDINATOR, "url": f"https://app.devin.ai/sessions/{COORDINATOR}"}

    def get_session(self, session_id: str) -> dict[str, Any]:
        if session_id == COORDINATOR:
            # The coordinator spawns its legs on the first poll.
            self.children = list(LEGS)
        return {
            "session_id": session_id,
            "status": "running",
            "status_detail": "finished",
            "url": f"https://app.devin.ai/sessions/{session_id}",
            "child_session_ids": self.children if session_id == COORDINATOR else [],
            "acus_consumed": 1.5,
        }

    def list_messages(self, session_id: str) -> list[dict[str, Any]]:
        if session_id == COORDINATOR:
            return [{"id": "c1", "type": "devin_message", "message": "[planner] Fanning out to two legs."}]
        index = LEGS.index(session_id) + 1
        return [
            {
                "id": f"{session_id}-1",
                "type": "devin_message",
                "message": f"[search] Leg {index} finished its MMseqs2 search. Evidence is CALCULATED.",
            }
        ]

    def list_attachments(self, session_id: str) -> list[dict[str, Any]]:
        return [
            {"name": name, "url": f"mem://{session_id}/{name}"}
            for name in self.per_session_files.get(session_id, {})
        ]

    def download(self, url: str) -> bytes:
        session_id, name = url.removeprefix("mem://").split("/", 1)
        return self.per_session_files[session_id][name]

    def list_playbooks(self) -> list[dict[str, Any]]:
        return []

    def get_playbook(self, playbook_id: str) -> dict[str, Any]:
        return {}

    def send_message(self, session_id: str, message: str) -> None:
        return None


@pytest.fixture
def fanout(monkeypatch, tmp_path: Path) -> FanoutDevin:
    settings.runs_dir = tmp_path
    settings.poll_interval_seconds = 0
    settings.poll_timeout_seconds = 5
    settings.poll_idle_timeout_seconds = 5
    fake = FanoutDevin()
    monkeypatch.setattr(executor, "get_client", lambda: fake)
    return fake


def run(fanout: FanoutDevin):
    job = store_module.store.create("Compare conservation across two targets", None, True)
    executor.run_job(job.id, client=fanout, sleep=lambda _s: None, now=time.monotonic)
    return store_module.store.get(job.id)


def test_legs_are_discovered_from_child_session_ids(fanout: FanoutDevin) -> None:
    job = run(fanout)

    assert [r.devin_session_id for r in job.runs] == list(LEGS)
    assert all(r.session_url for r in job.runs), "each leg needs a link back to Devin"
    assert all(r.acus_consumed == 1.5 for r in job.runs)


def test_leg_artifacts_land_in_their_own_directories(fanout: FanoutDevin) -> None:
    job = run(fanout)

    assert sorted(leg_ids(job.id)) == sorted(r.id for r in job.runs)
    for run_record in job.runs:
        assert (run_dir(job.id, run_record.id) / "conservation.json").is_file()


def test_the_flat_layout_the_ui_reads_still_resolves(fanout: FanoutDevin) -> None:
    job = run(fanout)

    flat = job_dir(job.id)
    # Bare filenames are what api.ts fetches.
    assert (flat / "conservation.json").is_file()
    assert (flat / "final_result.json").is_file(), "coordinator output stays at the job level"
    listed = [a.filename for a in job.artifacts]
    assert "conservation.json" in listed


def test_a_colliding_leg_file_is_preserved_not_overwritten(fanout: FanoutDevin) -> None:
    job = run(fanout)

    flat = job_dir(job.id)
    prefixed = [p.name for p in flat.iterdir() if p.name.endswith("__conservation.json")]
    assert prefixed, "the second leg's conservation must survive the name collision"
    bodies = {(flat / "conservation.json").read_text(), (flat / prefixed[0]).read_text()}
    assert len(bodies) == 2, "both legs' distinct results are on disk"


def test_leg_chat_joins_the_single_message_stream(fanout: FanoutDevin) -> None:
    job = run(fanout)

    bodies = " ".join(message.body for message in job.messages)
    assert "Leg 1 finished" in bodies
    assert "Leg 2 finished" in bodies
    # The existing speaker vocabulary carries them; no new UI concept needed.
    assert {m.speaker.value for m in job.messages} <= {
        "user", "planner", "search", "structure", "design", "reviewer", "system",
    }


def test_the_job_still_completes(fanout: FanoutDevin) -> None:
    job = run(fanout)

    assert job.status is JobStatus.complete
